-- Phase 3d: seed data. Pipeline stages, the three Jotform forms with their question maps and
-- field maps, and the positions currently on the English form's dropdowns.
--
-- Generated from reference/jotform-forms.json (question lists captured 2026-10-23) and
-- docs/positions-seed.csv. Department, hiring manager and pay range are blank in the CSV and
-- stay null here; fill them in through the app or a later migration.
-- Every insert is `on conflict do nothing` so re-running on a database that already has the
-- rows (local `db reset` after a seed, say) changes nothing.

-- ---------------------------------------------------------------------------------------------
-- stages
-- ---------------------------------------------------------------------------------------------

insert into recruiting.stages (id, name, sort_order, is_terminal, is_hired) values
  (1, 'Applied',         10, false, false),
  (2, 'Reviewed',        20, false, false),
  (3, 'Sent to manager', 30, false, false),
  (4, 'Interview',       40, false, false),
  (5, 'Offer',           50, false, false),
  (6, 'Hired',           60, true,  true),
  (7, 'Not selected',    70, true,  false),
  (8, 'Withdrawn',       80, true,  false)
on conflict (id) do nothing;

-- The identity sequence must continue past the explicit ids above.
select setval(pg_get_serial_sequence('recruiting.stages', 'id'),
              (select max(id) from recruiting.stages));

-- ---------------------------------------------------------------------------------------------
-- forms
-- ---------------------------------------------------------------------------------------------

