ruction Lead","Landscape Maintenance Crew Lead":"Landscape Maintenance Crew Lead","Landscape Maintenance Crew Member":"Landscape Maintenance Crew Member"},"order":"7","text":"What position are you applying for in Central Oregon?","type":"control_dropdown"},"342":{"name":"whatLocation","options":{"Central Oregon":"Central Oregon","Eugene/Springfield":"Eugene/Springfield","Lake Oswego":"Lake Oswego"},"order":"4","text":"What location are you applying to?","type":"control_dropdown"},"343":{"name":"whatPosition","options":{"Any":"Any","Blower Truck Crew Member":"Blower Truck Crew Member","Blower Truck Operator":"Blower Truck Operator"},"order":"5","text":"What position are you applying for in Lake Oswego?","type":"control_dropdown"},"344":{"name":"pleaseCheck","options":{"Associates Degree":"Associates Degree","Bachelor's Degree":"Bachelor's Degree","Certification(s)":"Certification(s)","GED":"GED","Graduate Degree":"Graduate Degree","High School Diploma":"High School Diploma","None":"None"},"order":"37","text":"Please check your highest level of education:","type":"control_radio"},"348":{"name":"startDate","order":"49","text":"Start Date (MM/YEAR)","type":"control_textbox"},"349":{"name":"startAnd349","order":"61","text":"Start Date (MM/YEAR)","type":"control_textbox"},"35":{"name":"classOr35","order":"32","text":"Class or Type of License","type":"control_textbox"},"350":{"name":"startAnd350","order":"73","text":"Start Date (MM/YEAR)","type":"control_textbox"},"352":{"name":"reasonFor352","order":"53","text":"Reason for leaving (please be specific)","type":"control_textbox"},"355":{"name":"whoReferred","order":"9","text":"Who referred you?","type":"control_textbox"},"362":{"name":"input362","order":"39","text":"Please list your complete job history in order of occurance. Begin with your current or most recent job (if unemployed). ","type":"control_text"},"363":{"name":"input363","order":"48","text":"Dates of employment:","type":"control_text"},"364":{"name":"ltpgtltstronggtdatesOf","order":"60","text":"Dates of employment:","type":"control_text"},"365":{"name":"ltpgtltstronggtdatesOf365","order":"72","text":"Dates of employment:","type":"control_text"},"368":{"name":"input368","order":"33","text":"I, the undersigned, hereby authorize Rexius Forest By-Products, Inc. to procure a Motor Vehicle Record (MVR) report. I understand that this report may include information about my driving record, including but not limited to traffic citations, accidents, driving offenses, and other related data. I acknowledge that Rexius may rely on this report to make decisions about my application, employment, or other related considerations.\r\nI understand that I have rights under the Fair Credit Reporting Act (FCRA), including the right to know if adverse action has been taken based on the information in the MVR report, and the right to verify the accuracy and completeness of any information provided by the consumer reporting agency.\r\nI acknowledge that this authorization will remain in effect until I revoke it in writing, and I agree that a copy of this authorization is as valid as the original.\r\nBy signing below, I affirm my understanding and consent to the above terms.","type":"control_text"},"369":{"name":"signature","order":"34","text":"Signature","type":"control_signature"},"370":{"name":"input370","order":"29","text":"You selected to apply for a job which requires driving a company vehicle. Please fill out the information below.","type":"control_text"},"372":{"name":"pleaseList","order":"41","text":"Please list any relevant skills or experiences.","type":"control_textarea"},"377":{"name":"endDate","order":"50","text":"End Date (MM/YEAR)","type":"control_textbox"},"378":{"name":"endDate378","order":"62","text":"End Date (MM/YEAR)","type":"control_textbox"},"379":{"name":"endDate379","order":"74","text":"End Date (MM/YEAR)","type":"control_textbox"},"380":{"name":"pleaseDescribe","order":"47","text":"Please describe your role and responsibilities","type":"control_textarea"},"381":{"name":"pleaseDescribe381","order":"59","text":"Please describe your role and responsibilities","type":"control_textarea"},"382":{"name":"pleaseDescribe382","order":"71","text":"Please describe your role and responsibilities","type":"control_textarea"},"384":{"name":"howDid","order":"10","text":"How did you learn about the position?","type":"control_textbox"},"385":{"name":"ifYou385","options":{"I am currently a student":"I am currently a student","I do not have job experience to enter":"I do not have job experience to enter"},"order":"40","text":"If you have not yet had a job or are a student, please check the appropriate box below.","type":"control_checkbox"},"386":{"name":"doYou","options":{"No":"No","Yes":"Yes"},"order":"27","text":"Do you have forklift experience?","type":"control_radio"},"387":{"name":"ifYou387","order":"79","text":"If you have a resume you may upload it here:","type":"control_fileupload"},"393":{"name":"ifYou","order":"80","text":"If you have a portfolio you may upload it here:","type":"control_fileupload"},"394":{"name":"typeA","order":"81","text":"Link to Portfolio","type":"control_textbox"},"395":{"name":"doYou395","options":{"No":"No","Yes":"Yes"},"order":"28","text":"Do you have a valid Herbicide Spray Applicators License, or a valid Apprentice Herbicide Spray Applicators License?","type":"control_dropdown"},"5":{"name":"ltpgtltspanStylecolor","order":"2","text":"Rexius is an equal opportunity employer. Please complete this form fully, honestly and accurately.We appreciate your interest in employment with Rexius.","type":"control_text"},"66":{"name":"pleaseList66","order":"35","text":"Please list any currently valid and special motor vehicle, operator licenses or trade/craft certifications you hold.","type":"control_textarea"},"72":{"name":"1Name","order":"43","text":"1. Name of Employer","type":"control_textbox"},"75":{"name":"phoneNumber","order":"45","text":"Phone number","type":"control_phone"},"76":{"name":"yourJob","order":"46","text":"Your Job Title","type":"control_textbox"},"80":{"name":"supervisorsName80","order":"51","text":"Supervisor’s Name","type":"control_textbox"},"81":{"name":"supervisorsTitletitulo81","order":"52","text":"Supervisor’s Title","type":"control_textbox"},"83":{"name":"2Name","order":"55","text":"2. Name of Employer","type":"control_textbox"},"85":{"name":"location85","order":"56","text":"Location","type":"control_textbox"},"86":{"name":"phoneNumber86","order":"57","text":"Phone number","type":"control_phone"},"87":{"name":"yourJob87","order":"58","text":"Your Job Title /Responsibility","type":"control_textbox"},"9":{"name":"name","order":"17","text":"Name","type":"control_fullname"},"92":{"name":"supervisorsName","order":"63","text":"Supervisor’s Name","type":"control_textbox"},"93":{"name":"supervisorsTitletitulo93","order":"64","text":"Supervisor’s Title","type":"control_textbox"},"94":{"name":"reasonFor","order":"65","text":"Reason for leaving (please be specific)","type":"control_textbox"},"95":{"name":"3Name","order":"67","text":"3. Name of Employer","type":"control_textbox"},"98":{"name":"phoneNumber98","order":"69","text":"Phone number","type":"control_phone"},"99":{"name":"yourJob99","order":"70","text":"Your Job Title / Responsibility","type":"control_textbox"}}$json$::jsonb,
