insert into recruiting.forms (jotform_form_id, label, language, default_location, questions, field_map)
values (
  '232824275836160',
  'Employment Application-ESP 2025 (Spanish)',
  'es',
  null,
  $json${"105":{"name":"supervisorsName105","order":"70","text":"Supervisor’s Name / Nombre de Supervisor","type":"control_textbox"},"106":{"name":"supervisorsTitletitulo106","order":"71","text":"Supervisor’s Title / Título de Supervisor","type":"control_textbox"},"107":{"name":"reasonFor107","order":"72","text":"Reason for leaving (please be specific) / Motivo de la salida (por favor, sea específico)","type":"control_textbox"},"140":{"name":"pleaseExplain","order":"73","text":"Please explain any gaps greater than three months, in the above dates of employment (between one employer and another) / Explique cualquier brecha mayor a tres meses en las fechas de empleo anteriores (entre un empleador y otro) utilizando","type":"control_textarea"},"148":{"name":"name148","options":{"I can bend or reach 8-10 hours per day / Puedo doblarme o alcanzar de 8 a 10 horas al día.":"I can bend or reach 8-10 hours per day / Puedo doblarme o alcanzar de 8 a 10 horas al día.","I can sit 8-10 hours per day / Puedo sentarme de 8 a 10 horas al día.":"I can sit 8-10 hours per day / Puedo sentarme de 8 a 10 horas al día.","I can stand 8-10 hours per day / Puedo estar de pie de 8 a 10 horas al día.":"I can stand 8-10 hours per day / Puedo estar de pie de 8 a 10 horas al día.","I can twist or lift or reach 8-10 hours per day / Puedo torcerme, levantar o alcanzar de 8 a 10 horas al día.":"I can twist or lift or reach 8-10 hours per day / Puedo torcerme, levantar o alcanzar de 8 a 10 horas al día.","I can walk 8-10 hours per day / Puedo caminar de 8 a 10 horas al día.":"I can walk 8-10 hours per day / Puedo caminar de 8 a 10 horas al día."},"order":"75","text":"Please check ALL that apply to or describe your physical capabilities / Por favor, marque TODOS los que se apliquen o describan sus capacidades físicas.","type":"control_checkbox"},"195":{"name":"ifYou195","order":"82","text":"If you can perform the essential tasks of the job ONLY with an accommodation, then please respond to this question: How would you perform the tasks, and with what accommodations(s)? / Si puedes realizar las tareas esenciales del trabajo SOLAMENTE con un ajuste, por favor responde a esta pregunta: Cómo llevarías a cabo las tareas y con qué ajuste(s)?","type":"control_textbox"},"21":{"name":"name21","options":{"Email/ Correo electrónico":"Email/ Correo electrónico","Phone/ Teléfono":"Phone/ Teléfono"},"order":"23","text":"Preferred Contact Method/ Método de contacto preferido","type":"control_checkbox"},"217":{"name":"ltpgtltspanStylefontweight217","order":"90","text":"PLEASE READ THE ENTIRE FOLLOWING SECTION HERE AND ON THE NEXT PAGE BEFORE SIGNING. / POR FAVOR, LEE LA SIGUIENTE SECCIÓN COMPLETA AQUÍ Y EN LA PÁGINA SIGUIENTE ANTES DE FIRMAR.\r\nThen please sign this form at the bottom of the next page. Also, please initial each section in the center column indicating you have read that section. / Luego, por favor firma este formulario en la parte inferior de la siguiente página. Además, por favor pon iniciales en cada sección en la columna del centro para indicar que has leído esa sección.","type":"control_text"},"219":{"name":"ltpgtltspanStylefontweight219","order":"92","text":"Term, Condition, Expectation and/or Agreement / Término, Condición, Expectativa y/o Acuerdo\r\nI certify that the information I have provided on this Application Form and on my Resume (if any) is true to the best of my knowledge.\r\nRegarding this application, I understand that if the Company determines that I have made any false statements, answers or any misrepresentation or any omission of significant information, the Company is entitled to reject my Application, or if hired, to terminate my employment. / \r\nCertifico que la información que he proporcionado en este Formulario de Solicitud y en mi Currículum (si lo hubiera) es verdadera según mi leal saber y entender.\r\nRespecto a esta solicitud, entiendo que si la Compañía determina que he realizado declaraciones falsas, respuestas incorrectas o cualquier representación inexacta u omisión de información significativa, la Compañía tiene el derecho de rechazar mi solicitud, o si soy contratado, de terminar mi empleo.\r\n ","type":"control_text"},"22":{"name":"emailAddress","order":"22","text":"Email Address/ Correo electrónico","type":"control_email"},"238":{"name":"rexiusHas238","order":"104","text":"Rexius has requested that I take a drug/alcohol test under its Alcohol & Drug Policy as part of my application for employment. Accordingly, by my signature below, herby authorize Rexius, the Medical Review Officer and licensed laboratory selected by Rexius to perform a urinalysis on a urine specimen provided by me to test for drug use. I consent to this test and I also give my permission to the laboratory and Medical Review Officer to release the results of this drug test to Rexius. I agree that Rexius may use these results to determine my suitability for employment. If I am employed by Rexius I agree to any drug/alcohol testing the Company may require under its Alcohol and Drug Policy. If the laboratory finds the test invalid, and if the laboratory, Medical Review Officer or Rexius believe another test is appropriate, I agree to submit another specimen(s) for further testing. I understand that I will not be informed of the results of my pre-employment drug test unless I request it within 60 days of being notified of the disposition of my application. / Rexius ha solicitado que me someta a una prueba de drogas/alcohol según su Política de Alcohol y Drogas como parte de mi solicitud de empleo. En consecuencia, mediante mi firma a continuación, por la presente autorizo a Rexius, al Oficial de Revisión Médica y al laboratorio con licencia seleccionado por Rexius a realizar un análisis de orina en una muestra de orina proporcionada por mí para detectar el uso de drogas. Consiento en esta prueba y también doy mi permiso al laboratorio y al Oficial de Revisión Médica para divulgar los resultados de esta prueba de drogas a Rexius. Estoy de acuerdo en que Rexius puede utilizar estos resultados para determinar mi idoneidad para el empleo. Si soy empleado por Rexius, acepto someterme a cualquier prueba de drogas/alcohol que la Compañía pueda requerir según su Política de Alcohol y Drogas. Si el laboratorio encuentra que la prueba es inválida, y si el laboratorio, el Oficial de Revisión Médica o Rexius consideran que es apropiada otra prueba, acepto proporcionar otra(s) muestra(s) para pruebas adicionales. Entiendo que no se me informará de los resultados de mi prueba de drogas previa al empleo a menos que lo solicite en un plazo de 60 días a partir de la notificación sobre la decisión de mi solicitud.","type":"control_signature"},"261":{"name":"availableStart261","order":"15","text":"Available Start Date/ Fecha de inicio disponible","type":"control_datetime"},"263":{"name":"addressDireccion","order":"17","text":"Address/ Dirección","type":"control_address"},"264":{"name":"phoneNumber264","order":"18","text":"Phone Number/ Número de teléfono","type":"control_phone"},"265":{"name":"alternatePhone265","order":"20","text":"Alternate Phone Number/ Número de teléfono alternativo","type":"control_phone"},"266":{"name":"phoneType","options":{"Cell/ Cellular":"Cell/ Cellular","Home/ Casa":"Home/ Casa"},"order":"19","text":"Phone Type/ Tipo de teléfono","type":"control_radio"},"267":{"name":"phoneType267","options":{"Cell/ Cellular":"Cell/ Cellular","Home/ Casa":"Home/ Casa"},"order":"21","text":"Phone Type/ Tipo de teléfono","type":"control_radio"},"268":{"name":"name268","options":{"CareerAmerica/":"CareerAmerica/","Craigslist.com/":"Craigslist.com/","Facebook/":"Facebook/","Indeed.com/":"Indeed.com/","Instagram/":"Instagram/","Referral/ Referencia":"Referral/ Referencia","Rexius.com/":"Rexius.com/"},"order":"8","text":"How did you learn about this job position?/ Cómo se enteró de este puesto de trabajo?","type":"control_checkbox"},"272":{"name":"haveYou","options":{"No":"No","Yes/Si":"Yes/Si"},"order":"10","text":"Have you ever worked for Rexius or its affiliates before?/ Alguna vez has trabajado para Rexius o sus afiliados?","type":"control_radio"},"273":{"name":"ifYes273","order":"11","text":"If yes, please give dates of employment, location, and job title./ En caso afirmativo, indique las fechas de empleo, la ubicación y el título del trabajo.","type":"control_textarea"},"274":{"name":"haveYou274","options":{"No":"No","Yes/Si":"Yes/Si"},"order":"12","text":"Have you ever applied for work with Rexius or its affiliates before?/ ¿Alguna vez has solicitado trabajo con Rexius o sus afiliados antes?","type":"control_radio"},"275":{"name":"ifYes275","order":"13","text":"If yes, please give date, location, and job for which you applied?/ En caso afirmativo, indique la fecha, la ubicación y el trabajo para el que se postuló?","type":"control_textarea"},"276":{"name":"youMay276","order":"49","text":"You may comment on any other special qualifications you have related to this job or this company. / Puedes comentar sobre cualquier otra cualificación especial que tengas relacionada con este trabajo o esta empresa.","type":"control_textarea"},"280":{"name":"locationUbicacion","order":"40","text":"Location/ Ubicación","type":"control_textbox"},"287":{"name":"locationUbicacion287","order":"64","text":"Location / Ubicación","type":"control_textbox"},"296":{"name":"pleaseCheckonly296","options":{"I can lift, push, or pull more than 50 lbs on a regular basis / Puedo levantar, empujar o jalar más de 50 libras de manera regular.":"I can lift, push, or pull more than 50 lbs on a regular basis / Puedo levantar, empujar o jalar más de 50 libras de manera regular.","I can lift, push, or pull up to 10 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 10 libras de manera regular.":"I can lift, push, or pull up to 10 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 10 libras de manera regular.","I can lift, push, or pull up to 20 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 20 libras de manera regular.":"I can lift, push, or pull up to 20 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 20 libras de manera regular.","I can lift, push, or pull up to 30 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 30 libras de manera regular.":"I can lift, push, or pull up to 30 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 30 libras de manera regular.","I can lift, push, or pull up to 40 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 40 libras de manera regular.":"I can lift, push, or pull up to 40 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 40 libras de manera regular.","I can lift, push, or pull up to 50 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 50 libras de manera regular.":"I can lift, push, or pull up to 50 lbs on a regular basis / Puedo levantar, empujar o jalar hasta 50 libras de manera regular."},"order":"76","text":"Please check only one from the options below / Por favor, marca solo una de las opciones a continuación.","type":"control_radio"},"30":{"name":"driverLicense30","order":"27","text":"Driver License number/ Número de licencia de conducir","type":"control_textbox"},"31":{"name":"expirationDate31","order":"28","text":"Expiration Date/ Fecha de vencimiento","type":"control_datetime"},"311":{"name":"areYou","options":{"No":"No","Yes/ Si":"Yes/ Si"},"order":"24","text":"Are you at least 18 years of Age?/ Tienes al menos 18 años de edad?","type":"control_radio"},"312":{"name":"canYou","options":{"No":"No","Yes/Si":"Yes/Si"},"order":"25","text":"Can you, upon hiring, provide appropriate identification documenting and verifying your identity and your legal right to work in the USA?/ Puede, al momento de la contratación, proporcionar una identificación adecuada para documentar y verifique su identidad y su derecho legal a trabajar en los EE. UU.?","type":"control_radio"},"313":{"name":"regardingThejob313","options":{"No":"No","Yes / Si":"Yes / Si"},"order":"78","text":"1. Regarding the job for which you have applied, are you familiar with this job and do you understand the basic physical requirements needed to perform it? / 1. En cuanto al trabajo para el cual has solicitado, estás familiarizado con este trabajo y comprendes los requisitos físicos básicos necesarios para desempeñarlo?","type":"control_radio"},"314":{"name":"2If","options":{"No":"No","Yes / Si":"Yes / Si"},"order":"79","text":"2. If yes, are you physically able to perform this job safely and without a significant risk of substantial harm to yourself or to others? / 2. Si es así, ¿tienes la capacidad física para desempeñar este trabajo de manera segura y sin un riesgo significativo de daño sustancial para ti mismo o para otros?","type":"control_radio"},"316":{"name":"haveYou316","options":{"No":"No","Yes/ Si":"Yes/ Si"},"order":"84","text":"Have you ever been counseled, warned or disciplined for an unsafe work practice or other safety violation in the past year? ( Note: A “Yes” answer may not necessarily bar you from employment here.) / Alguna vez has recibido asesoramiento, advertencias o disciplina por prácticas laborales inseguras u otras violaciones de seguridad en el último año? (Nota: Una respuesta 'Sí' no necesariamente te excluye de empleo aquí).","type":"control_radio"},"318":{"name":"ifYesplease","order":"85","text":"If YES, please explain. / Si la respuesta es 'Sí', por favor explique.","type":"control_textarea"},"319":{"name":"haveYou319","options":{"No":"No","Yes/ Si":"Yes/ Si"},"order":"86","text":"Have you ever had a “near miss” on the job where you nearly missed being injured or injuring someone else in the past year? ( Note: A “Yes” answer may not necessarily bar you from employment here.) / Alguna vez has tenido un 'casi accidente' en el trabajo en el que estuviste a punto de resultar herido o de herir a otra persona en el último año? (Nota: Una respuesta 'Sí' no necesariamente te excluye de empleo aquí).","type":"control_radio"},"320":{"name":"ifYesplease320","order":"87","text":"If YES, please explain. / Si la respuesta es 'Sí', por favor explique.","type":"control_textarea"},"322":{"name":"rexiusBelieves322","options":{"No":"No","Yes / Si":"Yes / Si"},"order":"88","text":"Rexius believes that use of drugs or alcohol in the workplace is an unsafe work practice and creates increased risk to the consumer, fellow employees, customers and the public. Rexius is a Drug-Free and Alcohol-Free workplace. Use of illegal substances or abuse of controlled substances may result in disciplinary action or termination of employment.If employed, do you agree to abide by the Rexius Drug-Free and Alcohol-Free workplace standards? / Rexius considera que el uso de drogas o alcohol en el lugar de trabajo es una práctica laboral insegura y crea un mayor riesgo para el consumidor, los compañeros de trabajo, los clientes y el público. Rexius es un lugar de trabajo libre de drogas y alcohol. El uso de sustancias ilegales o el abuso de sustancias controladas puede dar lugar a medidas disciplinarias o a la terminación del empleo. Si eres empleado, ¿estás de acuerdo en cumplir con las normas de Rexius de un lugar de trabajo libre de drogas y alcohol?","type":"control_radio"},"323":{"name":"ifPresently","options":{"No":"No","Unemployed/NA / Desempleado/No aplica":"Unemployed/NA / Desempleado/No aplica","Yes/Si":"Yes/Si"},"order":"36","text":"If presently employed, may we contact your current employer to verify employment?/ Si está actualmente empleado, Podemos contactar a su empleador actual para verificar su empleo?","type":"control_radio"},"324":{"name":"initials","order":"93","text":"Initials / Iniciales","type":"control_textbox"},"325":{"name":"ltpgtltspanStylefontweight","order":"94","text":"Term, Condition, Expectation and/or Agreement / Término, Condición, Expectativa y/o Acuerdo\r\nIn the event I undergo a medical examination or evaluation as a part of the job placement process of the Company I agree to supply only information which is true to the best of my knowledge.\r\nRegarding this examination or evaluation, I understand that if the Company determines that I have made any false oral or written statements or answers or any misrepresentation or any omission of significant information to the Company or to the physician or to his or her representative, the Company is entitled to terminate my conditional or actual employment at any time. / \r\nEn caso de que me someta a un examen o evaluación médica como parte del proceso de colocación laboral de la Compañía, acepto proporcionar solo información que sea verdadera según mi leal saber y entender.\r\nRespecto a esta evaluación o examen, entiendo que si la Compañía determina que he realizado declaraciones falsas, respuestas incorrectas o cualquier representación inexacta u omisión de información significativa a la Compañía, al médico o a su representante, la Compañía tiene el derecho de dar por terminado mi empleo condicional o efectivo en cualquier momento.","type":"control_text"},"326":{"name":"initials326","order":"95","text":"Initials / Iniciales","type":"control_textbox"},"327":{"name":"ltpgtltspanStylefontweight327","order":"96","text":"Term, Condition, Expectation and/or Agreement / Término, Condición, Expectativa y/o Acuerdo\r\nI authorize any person, school, current employer, past employer, physician or organization with knowledge of me or my work to provide the Company or its agent or representative with any information or opinion about me in response to an inquiry by the Company.\r\nI release any such person, employer, physician or organization from any legal liability in making such statements or furnishing any and all information to the Company or to its representative or agent. / \r\nAutorizo a cualquier persona, escuela, empleador actual, empleador anterior, médico u organización que tenga conocimiento de mí o de mi trabajo a proporcionar a la Compañía o a su agente o representante cualquier información u opinión sobre mí en respuesta a una consulta de la Compañía.\r\nEximo a dicha persona, empleador, médico u organización de cualquier responsabilidad legal al hacer tales declaraciones o proporcionar cualquier información a la Compañía o a su representante o agente.","type":"control_text"},"328":{"name":"initials328","order":"97","text":"Initials / Iniciales","type":"control_textbox"},"329":{"name":"ltpgtltspanStylefontweight329","order":"98","text":"Term, Condition, Expectation and/or Agreement / Término, Condición, Expectativa y/o Acuerdo\r\nI authorize the Company or its agent or representative to check references regarding my employment and investigate any of the statements or answers provided by me on this Application or made to a physician or his or her representative (in the event of a medical examination or evaluation). The only exception to this authorization is where I have specifically requested in writing on this Application Form on the date below that no such inquiry be made. /\r\nAutorizo a la Compañía o a su agente o representante a verificar las referencias con respecto a mi empleo e investigar cualquiera de las declaraciones o respuestas proporcionadas por mí en esta Solicitud o hechas a un médico o su representante (en caso de un examen médico o evaluación). La única excepción a esta autorización es cuando he solicitado específicamente por escrito en esta Solicitud en la fecha a continuación que no se realice dicha investigación.","type":"control_text"},"330":{"name":"initials330","order":"99","text":"Initials / Iniciales","type":"control_textbox"},"331":{"name":"ltpgtltspanStylefontweight331","order":"100","text":"Term, Condition, Expectation and/or Agreement / Término, Condición, Expectativa y/o Acuerdo\r\nI understand that my employment at this Company is on an “at will” (that is, mutual consent) basis. Therefore I agree that either I or the Company has the proper right to terminate my employment with or without cause at any time. / \r\nEntiendo que mi empleo en esta Compañía es de tipo \"a voluntad\" (es decir, de consentimiento mutuo). Por lo tanto, estoy de acuerdo en que tanto yo como la Compañía tenemos el derecho apropiado de dar por terminado mi empleo, con o sin motivo, en cualquier momento.","type":"control_text"},"332":{"name":"initials332","order":"101","text":"Initials / Iniciales","type":"control_textbox"},"333":{"name":"iHave","order":"102","text":"I have read and understood, and I agree to this entire section above, entitled AGREEMENT & RELEASE. / He leído y comprendido, y estoy de acuerdo con toda la sección anterior titulada ACUERDO Y LIBERACIÓN.","type":"control_signature"},"340":{"name":"whatPosition340","options":{"Any":"Any","Credit & Collections Coordinator":"Credit & Collections Coordinator","Experienced Irrigation Lead":"Experienced Irrigation Lead","Experienced Irrigation Technician":"Experienced Irrigation Technician","Flatbed Truck Driver":"Flatbed Truck Driver","Heavy Diesel Truck Mechanic":"Heavy Diesel Truck Mechanic","Landscape Commercial Construction Project Lead":"Landscape Commercial Construction Project Lead","Landscape Construction Crew":"Landscape Construction Crew","Landscape Construction Lead":"Landscape Construction Lead","Landscape Construction Maintenance Lead":"Landscape Construction Maintenance Lead","Landscape Maintenance Crew Leader":"Landscape Maintenance Crew Leader","Landscape Residential Construction Project Lead":"Landscape Residential Construction Project Lead","Retail Yard Associate / Delivery Driver":"Retail Yard Associate / Delivery Driver","Skilled Landscape Construction Crew Member":"Skilled Landscape Construction Crew Member"},"order":"6","text":"What position are you applying for in Eugene-Springfield?/ Qué puesto estás solicitando en Eugene-Springfield?","type":"control_dropdown"},"341":{"name":"whatPosition341","options":{"Any":"Any","Irrigation Service Technician":"Irrigation Service Technician","Landscape Construction Crew Member":"Landscape Construction Crew Member","Landscape Construction Lead":"Landscape Construction Lead","Landscape Maintenance Crew Lead":"Landscape Maintenance Crew Lead","Landscape Maintenance Crew Member":"Landscape Maintenance Crew Member"},"order":"7","text":"What position are you applying for in Central Oregon?/ Qué puesto estás solicitando en Centro Oregon?","type":"control_dropdown"},"342":{"name":"whatLocation","options":{"Central Oregon/":"Central Oregon/","Eugene-Springfield/":"Eugene-Springfield/","Lake Oswego/":"Lake Oswego/"},"order":"4","text":"What location are you applying to?/ A qué ubicación está solicitando?","type":"control_dropdown"},"343":{"name":"whatPosition","options":{"":"","Any/":"Any/","Blower Truck Driver/":"Blower Truck Driver/","Landscape Material Blower Truck Crew Member/":"Landscape Material Blower Truck Crew Member/"},"order":"5","text":"What position are you applying for in Lake Oswego?/ Qué puesto estás solicitando en Lake Oswego?","type":"control_dropdown"},"344":{"name":"pleaseCheck","options":{"Associates Degree/ Título de Asociado":"Associates Degree/ Título de Asociado","Bachelor's Degree/ Licenciatura":"Bachelor's Degree/ Licenciatura","Certification(s)/ Certificatión(s)":"Certification(s)/ Certificatión(s)","GED":"GED","Graduate Degree/ Título de posgrado":"Graduate Degree/ Título de posgrado","High School Diploma/ Diploma de secundaria":"High School Diploma/ Diploma de secundaria","None/ Ninguno":"None/ Ninguno"},"order":"33","text":"Please check your highest level of education:/ Por favor, compruebe su nivel más alto de educación:","type":"control_radio"},"348":{"name":"startDate","order":"44","text":"Start Date (MM/YEAR) / Fecha de inicio (MM/AÑO)","type":"control_textbox"},"349":{"name":"startAnd349","order":"56","text":"Start Date (MM/YEAR) / Fecha de inicio (MM/AÑO)","type":"control_textbox"},"35":{"name":"classOr35","order":"29","text":"Class or Type of License/Clase o tipo de licencia","type":"control_textbox"},"350":{"name":"startAnd350","order":"68","text":"Start Date (MM/YEAR) / Fecha de inicio (MM/AÑO)","type":"control_textbox"},"352":{"name":"reasonFor352","order":"48","text":"Reason for leaving (please be specific)/ Motivo de la salida (por favor, sea específico)","type":"control_textbox"},"355":{"name":"whoReferred","order":"9","text":"Who referred you?/ Quién te refirió?","type":"control_textbox"},"356":{"name":"haveMore","options":{"Yes, I have more job experience to enter./ Sí, tengo más experiencia laboral para ingresar.":"Yes, I have more job experience to enter./ Sí, tengo más experiencia laboral para ingresar."},"order":"50","text":"Have more job experience to enter? Check the box below./ Tienes más experiencia laboral para ingresar? Marque la casilla a continuación.","type":"control_radio"},"358":{"name":"haveMore358","options":{"Yes, I have more job history to enter. / Sí, tengo más experiencia laboral para ingresar.":"Yes, I have more job history to enter. / Sí, tengo más experiencia laboral para ingresar."},"order":"61","text":"Have more job experience to enter? Check the box below. / Tienes más experiencia laboral para ingresar? Marque la casilla a continuación.","type":"control_radio"},"362":{"name":"input362","order":"35","text":"Please list your complete job history in order of occurance. Begin with your current or most recent job (if unemployed). / Por favor, enumere su historial de trabajo completo. Comience con su trabajo actual o más reciente (si esta desempleado).","type":"control_text"},"363":{"name":"input363","order":"43","text":"Dates of employment: /&nbsp;Fechas de empleo:","type":"control_text"},"364":{"name":"ltpgtltstronggtdatesOf","order":"55","text":"Dates of employment: /&nbsp;Fechas de empleo:","type":"control_text"},"365":{"name":"ltpgtltstronggtdatesOf365","order":"67","text":"Dates of employment: /&nbsp;Fechas de empleo:","type":"control_text"},"368":{"name":"input368","order":"30","text":"I, the undersigned, hereby authorize Rexius Forest By-Products, Inc. to procure a Motor Vehicle Record (MVR) report. I understand that this report may include information about my driving record, including but not limited to traffic citations, accidents, driving offenses, and other related data. I acknowledge that Rexius&nbsp;may rely on this report to make decisions about my application, employment, or other related considerations.\nI understand that I have rights under the Fair Credit Reporting Act (FCRA), including the right to know if adverse action has been taken based on the information in the MVR report, and the right to verify the accuracy and completeness of any information provided by the consumer reporting agency.\nI acknowledge that this authorization will remain in effect until I revoke it in writing, and I agree that a copy of this authorization is as valid as the original.\nBy signing below, I affirm my understanding and consent to the above terms./&nbsp;\nYo, el abajo firmante, autorizo a Rexius Forest By-Products, Inc. A obtener un informe del Registro de Veh&iacute;culos Motorizados (MVR). Entiendo que este informe puede incluir informaci&oacute;n sobre mi historial de manejo, que incluye, entre otros, citaciones de tr&aacute;fico, accidentes, infracciones de tr&aacute;fico y otros datos relacionados. Reconozco que Rexius puede basarse en este informe para tomar decisiones sobre mi solicitud, empleo u otras consideraciones relacionadas.\nEntiendo que tengo derechos bajo la Ley de Informes Justos de Cr&eacute;dito (FCRA), incluido el derecho a saber si se ha tomado una medida adversa basada en la informaci&oacute;n en el informe MVR, y el derecho a verificar la precisi&oacute;n y integridad de cualquier informaci&oacute;n proporcionada por la agencia de informes del consumidor.\nReconozco que esta autorizaci&oacute;n permanecer&aacute; en vigor hasta que la revoque por escrito, y acepto que una copia de esta autorizaci&oacute;n tiene la misma validez que el original.\nAl firmar a continuaci&oacute;n, afirmo mi comprensi&oacute;n y consentimiento a los t&eacute;rminos anteriores.","type":"control_text"},"369":{"name":"signatureFrima","order":"31","text":"Signature/ Frima","type":"control_signature"},"370":{"name":"input370","order":"26","text":"You selected to apply for a job which requires driving a company vehicle. Please fill out the information below./ Seleccionó solicitar un trabajo que requiere conducir un vehículo de la empresa. Por favor, rellene la siguiente información.","type":"control_text"},"371":{"name":"ifYou","options":{"Yes/ Si":"Yes/ Si"},"order":"37","text":"If you have not yet had a job or are a student. Please check the box below./ Si aún no has tenido un trabajo o eres un estudiante, por favor marca la casilla a continuación.","type":"control_radio"},"372":{"name":"ifYou372","order":"38","text":"If you have not yet had a job or are a student. Please list any relevant skills or experiences./ Si aún no has tenido un trabajo o eres un estudiante, por favor enumera cualquier habilidad o experiencia relevante.","type":"control_textarea"},"373":{"name":"input373","order":"81","text":"*You may answer “Yes” to question #2 above if you can perform all essential functions of the job with or without reasonable accommodation. The Company will provide reasonable accommodation to a person with a disability. However, you still are not required to identify yourself as a disabled person on this Application Form. / Puedes responder 'Sí' a la pregunta #2 anterior si puedes desempeñar todas las funciones esenciales del trabajo con o sin ajustes razonables. La Compañía proporcionará ajustes razonables a una persona con discapacidad. Sin embargo, no estás obligado a identificarte como una persona discapacitada en este Formulario de Solicitud.","type":"control_text"},"375":{"name":"startAnd375","order":"45","text":"End Date (MM/YEAR) / Fecha de finalización (MM/AÑO)","type":"control_textbox"},"376":{"name":"endDate","order":"57","text":"End Date (MM/YEAR) / Fecha de finalización (MM/AÑO)","type":"control_textbox"},"377":{"name":"endDate377","order":"69","text":"End Date (MM/YEAR) / Fecha de finalización (MM/AÑO)","type":"control_textbox"},"5":{"name":"ltpgtltspanStylecolor","order":"2","text":"Rexius is an equal opportunity employer. Please complete this form fully, honestly and accurately. At the end of this application, you will be prompted to complete a questionairre. To have your application considered, you must complete the questionairre. We appreciate your interest in employment with Rexius./\r\nRexius es un empleador que ofrece igualdad de oportunidades. Complete este formulario de manera completa, honesta y precisa. Al final de esta solicitud, se le pedirá que complete un cuestionario. Para que se considere su solicitud, debe completar el cuestionario. Apreciamos su interés en trabajar con Rexius. ","type":"control_text"},"66":{"name":"pleaseList66","order":"106","text":"Please list any currently valid and special motor vehicle, operator licenses or trade/craft certifications you hold./ Por favor, enumere cualquier vehículo de motor, licencia de operador o certificación comercial/vehiculo actualmente válida y especial que tenga.","type":"control_textarea"},"72":{"name":"1Name","order":"39","text":"1. Name of Employer/ Nombre de empleador","type":"control_textbox"},"75":{"name":"phoneNumber","order":"41","text":"Phone number/ Número de teléfono","type":"control_phone"},"76":{"name":"yourJob","order":"42","text":"Your Job Title / Responsibility / Su Puesto de Trabajo / Responsabilidad","type":"control_textbox"},"80":{"name":"supervisorsName80","order":"46","text":"Supervisor’s Name/ Nombre de Supervisor","type":"control_textbox"},"81":{"name":"supervisorsTitletitulo81","order":"47","text":"Supervisor’s Title/ Título de Supervisor","type":"control_textbox"},"83":{"name":"2Name","order":"51","text":"2. Name of Employer/ Nombre de empleador","type":"control_textbox"},"85":{"name":"location85","order":"52","text":"Location/ Ubicación","type":"control_textbox"},"86":{"name":"phoneNumber86","order":"53","text":"Phone number / Número de teléfono","type":"control_phone"},"87":{"name":"yourJob87","order":"54","text":"Your Job Title /Responsibility / Su Puesto de Trabajo / Responsabilidad","type":"control_textbox"},"9":{"name":"nameNombre","order":"16","text":"Name/ Nombre","type":"control_fullname"},"92":{"name":"supervisorsName","order":"58","text":"Supervisor’s Name / Nombre de Supervisor","type":"control_textbox"},"93":{"name":"supervisorsTitletitulo93","order":"59","text":"Supervisor’s Title / Título de Supervisor","type":"control_textbox"},"94":{"name":"reasonFor","order":"60","text":"Reason for leaving (please be specific) Motivo de la salida (por favor, sea específico)","type":"control_textbox"},"95":{"name":"3Name","order":"63","text":"3. Name of Employer / Nombre de empleador","type":"control_textbox"},"98":{"name":"phoneNumber98","order":"65","text":"Phone number / Número de teléfono","type":"control_phone"},"99":{"name":"yourJob99","order":"66","text":"Your Job Title / Responsibility / Su Puesto de Trabajo / Responsabilidad","type":"control_textbox"}}$json$::jsonb,
  $json${"address":"263","applied_before":"274","available_start":"261","contact_method":"21","education":"344","email":"22","employers":[{"end":"375","location":"280","name":"72","reason":"352","start":"348","title":"76"},{"end":"376","location":"85","name":"83","reason":"94","start":"349","title":"87"},{"end":"377","location":"287","name":"95","reason":"107","start":"350","title":"99"}],"location":"342","name":"9","never_import":["30","31","35","238","333","369","324","325","326","327","328","329","330","331","332"],"phone":"264","phone_alt":"265","phone_type":"266","position":{"Central Oregon":"341","Eugene/Springfield":"340","Lake Oswego":"343"},"referred_by":"355","relevant_skills":"372","source":"268","worked_before":"272"}$json$::jsonb
)
