n is as valid as the original.\r\nBy signing below, I affirm my understanding and consent to the above terms.","type":"control_text"},"369":{"name":"signature","order":"28","text":"Signature","type":"control_signature"},"370":{"name":"input370","order":"23","text":"You selected to apply for a job which requires driving a company vehicle. Please fill out the information below.","type":"control_text"},"371":{"name":"ifYou","options":{"Yes":"Yes"},"order":"35","text":"If you have not yet had a job or are a student. Please check the box below.","type":"control_radio"},"372":{"name":"ifYou372","order":"36","text":"If you have not yet had a job or are a student. Please list any relevant skills or experiences.","type":"control_textarea"},"373":{"name":"input373","order":"79","text":"*You may answer “Yes” to question #2 above if you can perform all essential functions of the job with or without reasonable accommodation. The Company will provide reasonable accommodation to a person with a disability. However, you still are not required to identify yourself as a disabled person on this Application Form.","type":"control_text"},"375":{"name":"whatPosition","order":"4","text":"What position are you applying for?","type":"control_textbox"},"376":{"name":"howDid","options":{"Craigslist.com":"Craigslist.com","Facebook":"Facebook","Indeed.com":"Indeed.com","Instagram":"Instagram","Referral":"Referral","Rexius.com":"Rexius.com"},"order":"5","text":"How did you learn about this job position?","type":"control_checkbox"},"377":{"name":"whoReferred","order":"6","text":"Who referred you?","type":"control_textbox"},"378":{"name":"endDate","order":"43","text":"End Date (MM/YEAR)","type":"control_textbox"},"379":{"name":"endDate379","order":"55","text":"End Date (MM/YEAR)","type":"control_textbox"},"380":{"name":"endDate380","order":"67","text":"End Date (MM/YEAR)","type":"control_textbox"},"381":{"name":"ifYou381","order":"71","text":"If you have a resume you may upload it here:","type":"c