-- ---------------------------------------------------------------------------------------------
-- positions (from docs/positions-seed.csv)
-- ---------------------------------------------------------------------------------------------

-- No natural key exists yet (the same title can be reopened later), so guard on
-- (title, location) for this one seed only.
insert into recruiting.positions (title, location, department, hiring_manager, pay_min, pay_max, pay_unit, status, jotform_option_label)
select v.title, v.location, nullif(v.department, ''), nullif(v.hiring_manager, ''),
       nullif(v.pay_min, '')::numeric, nullif(v.pay_max, '')::numeric, nullif(v.pay_unit, ''),
       v.status::recruiting.position_status, v.jotform_option_label
from (values

  ('Residential Landscape Construction Manager', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Residential Landscape Construction Manager'),
  ('Irrigation Installation Crew Member', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Irrigation Installation Crew Member'),
  ('Commercial Landcape Project Lead', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Commercial Landcape Project Lead'),
  ('Commercial Landscape Crew Member', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Commercial Landscape Crew Member'),
  ('Digital Marketer', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Digital Marketer'),
  ('Landscape Maintenance Crew Member', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Landscape Maintenance Crew Member'),
  ('Commercial Landscape Crew Lead', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Commercial Landscape Crew Lead'),
  ('Flatbed Truck Driver', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Flatbed Truck Driver'),
  ('Experienced Irrigation Technician', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Experienced Irrigation Technician'),
  ('Landscape Maintenance Crew Leader', 'Eugene/Springfield', '', '', '', '', '', 'open', 'Landscape Maintenance Crew Leader'),
  ('Landscape Maintenance Crew Member', 'Central Oregon', '', '', '', '', '', 'open', 'Landscape Maintenance Crew Member'),
  ('Landscape Maintenance Crew Lead', 'Central Oregon', '', '', '', '', '', 'open', 'Landscape Maintenance Crew Lead'),
  ('Landscape Construction Crew Member', 'Central Oregon', '', '', '', '', '', 'open', 'Landscape Construction Crew Member'),
  ('Landscape Construction Lead', 'Central Oregon', '', '', '', '', '', 'open', 'Landscape Construction Lead'),
  ('Irrigation Service Technician', 'Central Oregon', '', '', '', '', '', 'open', 'Irrigation Service Technician'),
  ('Blower Truck Operator', 'Lake Oswego', '', '', '', '', '', 'open', 'Blower Truck Operator'),
  ('Blower Truck Crew Member', 'Lake Oswego', '', '', '', '', '', 'open', 'Blower Truck Crew Member')

) as v(title, location, department, hiring_manager, pay_min, pay_max, pay_unit, status, jotform_option_label)
where not exists (
  select 1 from recruiting.positions p where p.title = v.title and p.location = v.location
);
